"""Hand-written test questions with their gold plans. Phrased the way a person asks, not
from the generator's templates. engine/make_tests.py turns Q into data/tests.jsonl."""

def F(dim, value, op="="): return {"dim": dim, "op": op} if value is None else {"dim": dim, "op": op, "value": value}
def FL(flag): return {"flag": flag}
def T(period, **kw): return {"period": period, **kw}
def desc(m): return [{"measure": m, "dir": "desc"}]
def asc(m): return [{"measure": m, "dir": "asc"}]
def ddesc(d): return [{"dim": d, "dir": "desc"}]
def dasc(d): return [{"dim": d, "dir": "asc"}]

